/* The gate copies this beside the retained probe with its entry renamed. */
#include "probe.c"
static int inspect_code(void** object,const char* object_path,const char* image_path,const char* frozen_path,const char* oracle_path,const char* option){
 void* image=NULL;void* names=NULL;void* map=NULL;struct ube_gc_root roots[3]={{0}};CHECK(ube_gc_root_enter(&roots[0],&image) && ube_gc_root_enter(&roots[1],&names) && ube_gc_root_enter(&roots[2],&map) && retention_load(object,object_path)==0 && retention_load(&image,image_path)==0);
 struct expected_definition* rows=NULL;int32_t count;CHECK(retention_expected(&names,frozen_path,&rows,&count)==0);struct inventory_env a,b;struct layout ol,il;CHECK(retention_prepare(&a,object,&ol)==0 && retention_prepare(&b,&image,&il)==0);
 CHECK(ol.section_count>0 && ol.section_count<=96 && ube_value_try_resize(&map,ol.section_count,&code_map_layout,0));struct retained_definition* mapped=(struct retained_definition*)payload(map);struct inspection state;inspection_defaults(&state);struct failure failure;
 for(int i=0;i<count;++i){if(rows[i].bytes)continue;struct retained_definition anchor;CHECK(bind_definition(&rows[i],&names,&a.value,object,&ol,&b.value,&image,&il,&state,&anchor,NULL,&failure));if(!anchor.present)continue;int si=anchor.object.section;CHECK(si>=0 && si<ol.section_count);
  if(!mapped[si].present){int ok=validate_code(&anchor,&a.value,object,&ol,&b.value,&image,&il,&state,&mapped[si],NULL,&failure);if(!ok)fprintf(stderr,"code contribution section=%d code=%d\n",si,failure.code);CHECK(ok && failure.code==0 && mapped[si].present==1);}
  if(option && strcmp(option,"--anchor-mismatch")==0)++anchor.image.offset;
  int ok=validate_code_anchor(&anchor,&mapped[si],&state,NULL,&failure);if(!ok)fprintf(stderr,"code anchor section=%d code=%d\n",si,failure.code);CHECK(ok && failure.code==0);
 }
 if(option && (strcmp(option,"--missing-coverage")==0 || strcmp(option,"--spurious-coverage")==0)){int first=-1,empty=-1;for(int i=0;i<ol.section_count;++i){if(mapped[i].present && first<0)first=i;if(!mapped[i].present && empty<0)empty=i;}CHECK(first>=0);if(strcmp(option,"--missing-coverage")==0)mapped[first].present=0;else {CHECK(empty>=0);mapped[empty]=mapped[first];}}
 int covered=validate_code_coverage(object,&ol,&map,&state,NULL,&failure);if(!covered)fprintf(stderr,"code coverage code=%d\n",failure.code);CHECK(covered && failure.code==0);
 FILE* file=fopen(oracle_path,"rb");int32_t expected_count;CHECK(file && fread(&expected_count,4,1,file)==1 && expected_count>=0 && expected_count<=96);int observed=0;int64_t bytes=0;
 for(int si=0;si<ol.section_count;++si){struct section s;CHECK(read_section(object,&state,&ol,si,&s,NULL,&failure));if(!(s.characteristics&0x20000000) || !s.raw_bytes){CHECK(!mapped[si].present);continue;}CHECK(mapped[si].present==1);int32_t index;struct definition_range expected_object,expected_image;CHECK(fread(&index,4,1,file)==1 && fread(&expected_object,56,1,file)==1 && fread(&expected_image,56,1,file)==1 && index==si);CHECK(memcmp(&mapped[si].object,&expected_object,56)==0 && memcmp(&mapped[si].image,&expected_image,56)==0);++observed;bytes+=mapped[si].object.count;}
 CHECK(observed==expected_count && fgetc(file)==EOF && fclose(file)==0);printf("PASS %d code contributions; %lld content bytes; %lld inspection bytes; %lld events\n",observed,(long long)bytes,(long long)state.bytes,(long long)state.events);
 if(option && option[0]!='-'){FILE* output=fopen(option,"wb");CHECK(output && fwrite(&observed,4,1,output)==1);for(int si=0;si<ol.section_count;++si)if(mapped[si].present){CHECK(count>0);struct owned_code record={0};record.unit=rows[0].unit;record.source=rows[0].source;record.contribution=mapped[si];for(int j=1;j<count;++j)CHECK(rows[j].unit==record.unit && rows[j].source==record.source);CHECK(fwrite(&record,128,1,output)==1);}CHECK(fclose(output)==0);}
 free(rows);CHECK(inventory_close(&b)==0 && inventory_close(&a)==0);image=names=map=NULL;CHECK(ube_gc_root_leave(&roots[2]) && ube_gc_root_leave(&roots[1]) && ube_gc_root_leave(&roots[0]));return 0;
}
static int inspect_code_owners(const char* path,int defect){
 FILE* input=fopen(path,"rb");int32_t count,sources;CHECK(input && fread(&count,4,1,input)==1 && fread(&sources,4,1,input)==1 && count>1 && count<=10000);void* records=NULL;struct ube_gc_root root={0};CHECK(ube_gc_root_enter(&root,&records) && ube_value_try_resize(&records,count,&owned_code_layout,0));struct owned_code* rows=(struct owned_code*)payload(records);CHECK(fread(rows,128,count,input)==(size_t)count);
 if(defect==1){rows[1].unit=rows[0].unit;rows[1].source=rows[0].source;rows[1].contribution.object.section=rows[0].contribution.object.section;}
 if(defect==2)rows[1].contribution.image.first=rows[0].contribution.image.first;
 if(defect==3){rows[1].contribution.image.rva=rows[0].contribution.image.rva;rows[1].contribution.image.address=rows[0].contribution.image.address;rows[1].contribution.image.offset=rows[0].contribution.image.offset;}
 struct code_index_env e;struct inspection state;struct failure failure;CHECK(code_index_open(&e)==0);inspection_defaults(&state);int ok=code_index_prepare(&e.value,&records,sources,&state,&e.storage,&e.limits,&e.usage,NULL,&failure);if(!ok)fprintf(stderr,"code ownership code=%d\n",failure.code);CHECK(ok && failure.code==0 && e.value.status==1 && e.value.count==count);int32_t* order=(int32_t*)payload(e.value.order);for(int i=0;i<count;++i){int32_t expected;CHECK(fread(&expected,4,1,input)==1 && order[i]==expected);}CHECK(fgetc(input)==EOF && fclose(input)==0 && e.storage.payload==4LL*count && e.storage.peak==25LL*count);printf("PASS %d owned code contributions; %lld peak bytes; %lld events\n",count,(long long)e.storage.peak,(long long)state.events);CHECK(code_index_close(&e)==0);records=NULL;CHECK(ube_gc_root_leave(&root));return 0;
}
int main(int argc,char** argv){if(argc==4 && strcmp(argv[1],"--ownership")==0){CHECK(inspect_code_owners(argv[2],atoi(argv[3]))==0);}else{CHECK(argc==5 || argc==6);void* object=NULL;struct ube_gc_root root={0};CHECK(ube_gc_root_enter(&root,&object));CHECK(inspect_code(&object,argv[1],argv[2],argv[3],argv[4],argc==6?argv[5]:NULL)==0);object=NULL;CHECK(ube_gc_root_leave(&root));}CHECK(ube_gc_collect() && ube_gc_root_count==0 && ube_gc_live_allocation_bytes()==0);return 0;}
